import { type Row, rowsToHtml } from "@/lib/shore/engine";

/**
 * Rows of coloured runs; colours come from the theme through data-c. Written
 * as one HTML string so a tick swaps the frame without reconciling thousands
 * of spans.
 */
export function AsciiRows({ rows }: { rows: Row[] }) {
	return (
		<div
			// biome-ignore lint/security/noDangerouslySetInnerHtml: generated by the engine from fixed glyphs, with &, < and > escaped
			dangerouslySetInnerHTML={{ __html: rowsToHtml(rows) }}
		/>
	);
}
